import 'dart:convert';
import 'dart:math' as math;
import 'package:file_picker/file_picker.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

const bg = Color(0xFF0B0E14), bg2 = Color(0xFF121620), card = Color(0xFF1A1F2C), surface = Color(0xFF242B3D), accent = Color(0xFFC9A9FF), cyan = Color(0xFF8DD8FF);

void main() => runApp(const StatsYuriApp());

class StatsYuriApp extends StatelessWidget {
  const StatsYuriApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(
    title: 'StatsYuri', debugShowCheckedModeBanner: false,
    theme: ThemeData(brightness: Brightness.dark, useMaterial3: true, scaffoldBackgroundColor: bg,
      colorScheme: const ColorScheme.dark(primary: accent, secondary: cyan, surface: card),
      inputDecorationTheme: const InputDecorationTheme(filled: true, fillColor: surface,
        contentPadding: EdgeInsets.symmetric(horizontal: 16, vertical: 15),
        border: OutlineInputBorder(borderRadius: BorderRadius.all(Radius.circular(16)), borderSide: BorderSide.none),
        enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.all(Radius.circular(16)), borderSide: BorderSide.none),
        focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.all(Radius.circular(16)), borderSide: BorderSide(color: accent, width: 1.2)))),
    home: const Home());
}

class Home extends StatefulWidget { const Home({super.key}); @override State<Home> createState() => _HomeState(); }
class _HomeState extends State<Home> with SingleTickerProviderStateMixin {
  static const channel = MethodChannel('statsyuri/python');
  String? path, name, error; String question = '', mode = 'efficient'; bool busy = false; Map<String,dynamic>? result;
  late AnimationController animation;
  @override void initState(){super.initState(); animation=AnimationController(vsync:this,duration:const Duration(seconds:22))..repeat();}
  @override void dispose(){animation.dispose();super.dispose();}
  Future<void> pick() async { final p=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['csv','xlsx','xls']); if(p?.files.single.path==null)return; setState((){path=p!.files.single.path;name=p.files.single.name;result=null;error=null;}); }
  Future<void> analyze() async {
    if(path==null){setState(()=>error='Choose a CSV or Excel dataset first.');return;}
    setState(()=>{busy=true,error=null,result=null});
    try { final raw=await channel.invokeMethod<String>('analyze',{'path':path,'question':question.trim(),'mode':mode}); final x=jsonDecode(raw??'{}'); setState(()=>result=Map<String,dynamic>.from(x)); }
    on PlatformException catch(e){setState(()=>error=e.message??e.code);} catch(e){setState(()=>error=e.toString());} finally{if(mounted)setState(()=>busy=false);}
  }
  @override Widget build(BuildContext context)=>Scaffold(
    appBar:AppBar(backgroundColor:Colors.transparent,surfaceTintColor:Colors.transparent,titleSpacing:18,title:const Row(children:[Mark(34),SizedBox(width:10),Text('StatsYuri',style:TextStyle(fontWeight:FontWeight.w900))]),actions:[Container(margin:const EdgeInsets.only(right:16),padding:const EdgeInsets.symmetric(horizontal:10,vertical:6),decoration:BoxDecoration(color:surface,borderRadius:BorderRadius.circular(30)),child:const Text('OFFLINE',style:TextStyle(fontSize:10,fontWeight:FontWeight.w900))) ]),
    body:Stack(children:[Positioned.fill(child:AnimatedBuilder(animation:animation,builder:(_,__)=>CustomPaint(painter:DataBg(animation.value)))),SafeArea(child:ListView(padding:const EdgeInsets.fromLTRB(18,10,18,42),children:[
      Row(crossAxisAlignment:CrossAxisAlignment.start,children:[const Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Statistical Analysis',style:TextStyle(fontSize:27,fontWeight:FontWeight.w900)),SizedBox(height:7),Text('Analyze locally. See the reasoning and calculations without sending your data anywhere.',style:TextStyle(color:Colors.white60,fontSize:14,height:1.45))])),const SizedBox(width:12),const Mark(58)]),
      const SizedBox(height:20),
      CardBox(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const TitleRow(Icons.dataset_rounded,'Dataset'),const SizedBox(height:12),InkWell(onTap:busy?null:pick,borderRadius:BorderRadius.circular(16),child:Container(width:double.infinity,padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:surface,borderRadius:BorderRadius.circular(16)),child:Row(children:[const Icon(Icons.upload_file_rounded,color:cyan),const SizedBox(width:12),Expanded(child:Text(name??'Choose CSV / Excel dataset',style:TextStyle(fontWeight:FontWeight.w800))),const Icon(Icons.chevron_right_rounded)])))])),
      const SizedBox(height:14),
      CardBox(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const TitleRow(Icons.auto_awesome_rounded,'Ask StatsYuri'),const SizedBox(height:6),const Text('Optional. Leave it empty and StatsYuri will analyze the dataset automatically.',style:TextStyle(color:Colors.white60,fontSize:13,height:1.4)),const SizedBox(height:13),TextField(minLines:3,maxLines:6,onChanged:(v)=>question=v,style:const TextStyle(fontSize:15,height:1.45),decoration:const InputDecoration(hintText:'Example: Do crop yields differ among fertilizer groups?')),const SizedBox(height:14),Container(padding:const EdgeInsets.all(4),decoration:BoxDecoration(color:surface,borderRadius:BorderRadius.circular(17)),child:SegmentedButton<String>(showSelectedIcon:false,segments:const[ButtonSegment(value:'efficient',label:Text('Efficient'),icon:Icon(Icons.bolt_rounded,size:18)),ButtonSegment(value:'full',label:Text('Full analysis'),icon:Icon(Icons.analytics_rounded,size:18))],selected:{mode},onSelectionChanged:(v)=>setState(()=>mode=v.first))),const SizedBox(height:10),Text(mode=='full'?'Full mode checks every compatible analysis it can calculate from this dataset.':'Efficient mode selects one compatible analysis and explains it.',style:const TextStyle(color:Colors.white38,fontSize:12)),const SizedBox(height:14),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:busy?null:analyze,style:FilledButton.styleFrom(backgroundColor:accent,foregroundColor:Color(0xFF25183E),padding:const EdgeInsets.symmetric(vertical:16),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18))),icon:busy?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.search_rounded),label:Text(busy?'Analyzing…':'Analyze dataset',style:const TextStyle(fontWeight:FontWeight.w900,fontSize:15))))])),
      if(error!=null)Padding(padding:const EdgeInsets.only(top:14),child:CardBox(child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.error_outline_rounded,color:Color(0xFFFF9B9B)),const SizedBox(width:10),Expanded(child:Text(error!,style:const TextStyle(fontSize:14,height:1.4)))]))),
      if(result!=null)Output(result!),
    ]))]));
}

